-- ═══════════════════════════════════════════════════════════════════════════════
-- 020: Seed full club roster from Sem 2 1447/2025 Excel database.
-- Source: ~/Downloads/Copy of DRC Database 1447-2025 Semester 2.xlsx
--
-- Sheets used: الأعضاء (active), الأعضاء المجددين (renewed), القادة (leaders),
--              Graduates (alumni).
--
-- - password_hash = NULL → first login auto-emails 24h setup token.
-- - position derived from القادة sheet (قائد=leader, نائب=vice, رئيس=president).
-- - department derived from committee Arabic strings.
-- - English names auto-transliterated; members can edit them in /dashboard/profile.
-- - status = 'alumni' for Graduates; 'active' otherwise.
-- - Idempotent: re-running updates names/position/dept cleanly.
-- ═══════════════════════════════════════════════════════════════════════════════

BEGIN;

WITH dept AS (SELECT department_id, slug FROM departments)
ON CONFLICT (email) DO UPDATE SET
  position = EXCLUDED.position,
  department_id = EXCLUDED.department_id,
  is_active = EXCLUDED.is_active;


COMMIT;
